import type { PortableTextBlock } from "@portabletext/types";

/** Sanity image with metadata (LQIP for blur + intrinsic dimensions). */
interface SanityImage {
  alt?: string;
  asset?: {
    url?: string;
    metadata?: {
      /** Tiny Base64 generated by Sanity — instant blur placeholder. */
      lqip?: string;
      dimensions?: {
        width: number;
        height: number;
        aspectRatio: number;
      };
    };
  };
}

interface Author {
  name: string;
  slug: string;
  bio?: string;
  /** In the schema, the field is `avatar` (not `image`). */
  avatar?: SanityImage;
}

interface Category {
  title: string;
  slug: string;
  color?: string;
  /** Number of posts in this category — only included in the list query. */
  count?: number;
}

/** Post in the list view (without the Portable Text body; lighter). */
interface BlogPostCard {
  _id: string;
  title: string;
  slug: string;
  excerpt?: string;
  featuredImage?: SanityImage;
  publishedAt?: string;
  readTime?: number;
  author?: Pick<Author, "name" | "slug">;
  category?: Category;
}

/** FULL post (individual page). */
interface BlogPost extends BlogPostCard {
  content?: PortableTextBlock[];
  author?: Author;
  _updatedAt?: string;
  related?: BlogPostCard[];
  /** Flattened from `seo.metaTitle` in the query. */
  metaTitle?: string;
  /** Flattened from `seo.metaDescription` in the query. */
  metaDescription?: string;
  /** Flattened `seo.robots` — a string like "index, follow". */
  robots?: string;
}

interface BlogListResult {
  posts: BlogPostCard[];
  total: number;
  categories: Category[];
}

interface LegalPolicy {
  title: string;
  slug: string;
  description?: string;
  content?: PortableTextBlock[];
  _updatedAt?: string;
  metaTitle?: string;
  metaDescription?: string;
  /** String of type "index, follow" / "noindex, nofollow". */
  robots?: string;
}

/** Translates the `robots` string from the schema into the Next Metadata format. */
function parseRobots(robots?: string): { index: boolean; follow: boolean } {
  const value = robots?.toLowerCase() ?? "";

  return {
    index: !value.includes("noindex"),
    follow: !value.includes("nofollow"),
  };
}

export { parseRobots };

export type {
  SanityImage,
  Author,
  Category,
  BlogPostCard,
  BlogPost,
  BlogListResult,
  LegalPolicy,
};
